// 共通のサイドバー用スタイル
const sidebarStyles = `
    .sidebar-link { transition: all 0.2s; }
    .sidebar-link:hover { background-color: rgba(255,255,255,0.1); }
    .sidebar-link.active { background-color: rgba(255,255,255,0.2); border-left: 3px solid white; }
`;

// 共通のサイドバー用JavaScript
const sidebarScripts = `
    function checkAuth() {
        const token = localStorage.getItem('admin_token');
        if (!token) {
            window.location.href = '/login';
            return false;
        }
        return true;
    }
    
    function logout() {
        if (confirm('ログアウトしますか？')) {
            localStorage.removeItem('admin_token');
            localStorage.removeItem('admin_name');
            localStorage.removeItem('admin_username');
            localStorage.removeItem('admin_role');
            window.location.href = '/login';
        }
    }
    
    function toggleSidebar() {
        const sidebar = document.getElementById('sidebar');
        const overlay = document.getElementById('sidebarOverlay');
        sidebar.classList.toggle('-translate-x-full');
        overlay.classList.toggle('hidden');
    }
    
    // 認証確認
    if (!checkAuth()) {
        // リダイレクト処理は checkAuth 内で実行
    }
    
    // 管理者名を設定
    document.getElementById('sidebarAdminName').textContent = localStorage.getItem('admin_name') || '管理者';
    
    // adminロールのみの項目を表示
    if (localStorage.getItem('admin_role') === 'admin') {
        const employeeLink = document.getElementById('sidebarEmployeeLink');
        const paymentsLink = document.getElementById('sidebarPaymentsLink');
        const settingsLink = document.getElementById('sidebarSettingsLink');
        const backupLink = document.getElementById('sidebarBackupLink');
        if (employeeLink) employeeLink.classList.remove('hidden');
        if (paymentsLink) paymentsLink.classList.remove('hidden');
        if (settingsLink) settingsLink.classList.remove('hidden');
        if (backupLink) backupLink.classList.remove('hidden');
    }
    
    // Axios設定：認証ヘッダーを自動付与
    if (typeof axios !== 'undefined') {
        axios.defaults.headers.common['Authorization'] = 'Bearer ' + localStorage.getItem('admin_username') + ':' + localStorage.getItem('admin_role');
    }
    
    // 枠残数をサイドバーに表示 & 業務範囲ロック
    async function loadSidebarSlotBalance() {
        const badge = document.getElementById('slotsBadge');
        if (!badge) return;
        
        try {
            const response = await fetch('/api/subscription/status', {
                headers: {
                    'Authorization': 'Bearer ' + localStorage.getItem('admin_username') + ':' + localStorage.getItem('admin_role')
                }
            });
            
            if (!response.ok) {
                console.error('Slot balance API error:', response.status);
                badge.textContent = '!';
                badge.className = 'ml-auto bg-gray-400 text-white text-xs px-2 py-0.5 rounded-full';
                return;
            }
            
            const data = await response.json();
            if (data.is_unlimited) {
                // 無制限プラン
                badge.innerHTML = '<i class="fas fa-infinity text-xs"></i>';
                badge.className = 'ml-auto bg-purple-500 text-white text-xs px-2 py-0.5 rounded-full';
            } else {
                const total = data.total_available !== undefined ? data.total_available : 0;
                badge.textContent = total;
                badge.className = total > 0 
                    ? 'ml-auto bg-green-500 text-white text-xs px-2 py-0.5 rounded-full'
                    : 'ml-auto bg-red-500 text-white text-xs px-2 py-0.5 rounded-full';
            }
            
            // 業務範囲に応じてサイドバーをロック
            // デフォルトは 'both'（すべてアクセス可能）- 明示的に設定されている場合のみロック
            const scope = data.business_scope || 'both';
            console.log('Business scope from API:', data.business_scope, '-> Using:', scope);
            applyBusinessScopeLock(scope);
            
        } catch (error) {
            console.error('Error loading slot balance:', error);
            badge.textContent = '!';
            badge.className = 'ml-auto bg-gray-400 text-white text-xs px-2 py-0.5 rounded-full';
        }
    }
    
    // 業務範囲に応じてサイドバーのリンクをロック
    function applyBusinessScopeLock(scope) {
        console.log('applyBusinessScopeLock called with scope:', scope);
        
        const subsidyLink = document.getElementById('sidebarSubsidyLink');
        const subsidyIcon = document.getElementById('sidebarSubsidyIcon');
        const subsidyBadge = document.getElementById('sidebarSubsidyBadge');
        const grantLink = document.getElementById('sidebarGrantLink');
        const grantIcon = document.getElementById('sidebarGrantIcon');
        const grantBadge = document.getElementById('sidebarGrantBadge');
        const licenseLink = document.getElementById('sidebarLicenseLink');
        const licenseIcon = document.getElementById('sidebarLicenseIcon');
        const licenseBadge = document.getElementById('sidebarLicenseBadge');
        
        console.log('Sidebar elements found:', {
            subsidyLink: !!subsidyLink,
            grantLink: !!grantLink,
            licenseLink: !!licenseLink
        });
        
        // 社労士のみ: 補助金と許認可をロック
        if (scope === 'labor') {
            console.log('Labor scope: locking subsidy and license');
            if (subsidyLink) lockSidebarItem(subsidyLink, subsidyIcon, subsidyBadge, '行政書士業務', 'administrative');
            if (licenseLink) lockSidebarItem(licenseLink, licenseIcon, licenseBadge, '行政書士業務', 'administrative');
        }
        // 行政書士のみ: 助成金をロック
        else if (scope === 'administrative') {
            console.log('Administrative scope: locking grant only');
            if (grantLink) lockSidebarItem(grantLink, grantIcon, grantBadge, '社労士業務', 'labor');
        }
        // both: すべてアクセス可能
        else {
            console.log('Both scope: all features unlocked');
        }
    }
    
    // サイドバー項目をロック状態にする
    function lockSidebarItem(link, icon, badge, scopeName, scopeType) {
        // リンクを無効化
        link.href = 'javascript:void(0)';
        link.onclick = function(e) {
            e.preventDefault();
            showScopeLockModal(scopeName, scopeType);
        };
        link.classList.add('opacity-50', 'cursor-not-allowed');
        
        // アイコンをロックに変更
        if (icon) {
            icon.className = 'fas fa-lock w-5 text-gray-400';
        }
        
        // バッジをロック表示に変更
        if (badge) {
            badge.innerHTML = '<i class="fas fa-lock text-xs"></i>';
            badge.className = 'ml-auto text-xs bg-gray-500 px-2 py-0.5 rounded';
        }
    }
    
    // ロック解除モーダルを表示
    function showScopeLockModal(scopeName, scopeType) {
        // 既存のモーダルを削除
        const existingModal = document.getElementById('scopeLockModal');
        if (existingModal) existingModal.remove();
        
        const modal = document.createElement('div');
        modal.id = 'scopeLockModal';
        modal.className = 'fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50';
        modal.innerHTML = \`
            <div class="bg-white rounded-xl shadow-2xl max-w-md w-full mx-4 overflow-hidden">
                <div class="bg-gradient-to-r from-gray-600 to-gray-700 text-white p-6 text-center">
                    <div class="w-16 h-16 rounded-full bg-white/20 flex items-center justify-center mx-auto mb-4">
                        <i class="fas fa-lock text-3xl"></i>
                    </div>
                    <h3 class="text-xl font-bold">この機能はロックされています</h3>
                </div>
                <div class="p-6">
                    <p class="text-gray-600 mb-4 text-center">
                        <strong>\${scopeName}</strong>の機能を使用するには、<br>
                        オプションプランへの加入が必要です。
                    </p>
                    <div class="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-4">
                        <p class="text-sm text-blue-800">
                            <i class="fas fa-info-circle mr-2"></i>
                            <strong>月額 +¥2,000</strong> で\${scopeName}を追加できます。
                        </p>
                    </div>
                    <div class="flex gap-3">
                        <button onclick="document.getElementById('scopeLockModal').remove()" 
                                class="flex-1 px-4 py-3 border border-gray-300 rounded-lg hover:bg-gray-50">
                            閉じる
                        </button>
                        <a href="/admin/subscription" 
                           class="flex-1 px-4 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-center font-bold">
                            <i class="fas fa-arrow-right mr-2"></i>プラン管理へ
                        </a>
                    </div>
                </div>
            </div>
        \`;
        document.body.appendChild(modal);
        
        // モーダルの背景クリックで閉じる
        modal.addEventListener('click', function(e) {
            if (e.target === modal) {
                modal.remove();
            }
        });
    }
    
    // グローバルに公開
    window.showScopeLockModal = showScopeLockModal;
    
    // DOMContentLoadedを待ってから実行
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', loadSidebarSlotBalance);
    } else {
        loadSidebarSlotBalance();
    }
`;

// ===============================
// 認証機能
// ===============================

// ログインページ
app.get('/login', (c) => {
  return c.html(`
    <!DOCTYPE html>
    <html lang="ja">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>ログイン - 申請革命</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@6.4.0/css/all.min.css" rel="stylesheet">
    </head>
    <body class="bg-gray-50">
        <div class="min-h-screen flex items-center justify-center">
            <div class="bg-white p-8 rounded-lg shadow-lg max-w-md w-full">
                <div class="text-center mb-8">
                    <i class="fas fa-file-invoice-dollar text-5xl text-blue-600 mb-4"></i>
                    <h1 class="text-2xl font-bold text-gray-800">申請革命</h1>
                    <p class="text-sm text-gray-600 mt-2">管理者ログイン</p>
                </div>
                
                <form id="loginForm" class="space-y-4">
                    <div>
                        <label class="block text-sm font-medium mb-1">ユーザー名</label>
                        <input type="text" name="username" required 
                               class="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500">
                    </div>
                    <div>
                        <label class="block text-sm font-medium mb-1">パスワード</label>
                        <input type="password" name="password" required 
                               class="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500">
                    </div>
                    <button type="submit" 
                            class="w-full bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700">
                        ログイン
                    </button>
                </form>
                
                <div class="mt-6 text-center">
                    <p class="text-gray-600">
                        アカウントをお持ちでない方は 
                        <a href="/signup" class="text-blue-600 hover:underline font-medium">新規登録（14日間無料）</a>
                    </p>
                </div>
                
                <div class="mt-4 p-4 bg-blue-50 rounded-lg text-sm">
                    <p class="font-medium text-blue-800 mb-2">デモ用ログイン情報：</p>
                    <p class="text-blue-700">ユーザー名: <code class="bg-white px-2 py-1 rounded">admin</code></p>
                    <p class="text-blue-700">パスワード: <code class="bg-white px-2 py-1 rounded">admin123</code></p>
                </div>
                
                <div id="errorMessage" class="hidden mt-4 p-3 bg-red-50 text-red-700 rounded-lg text-sm"></div>
                
                <!-- フッターリンク -->
                <div class="mt-6 pt-4 border-t text-center text-xs text-gray-500">
                    <a href="/legal" class="hover:text-blue-600">特定商取引法に基づく表記</a>
                    <span class="mx-2">|</span>
                    <a href="/terms" class="hover:text-blue-600">利用規約</a>
                    <span class="mx-2">|</span>
                    <a href="/privacy-policy" class="hover:text-blue-600">プライバシーポリシー</a>
                </div>
            </div>
        </div>

        <script src="https://cdn.jsdelivr.net/npm/axios@1.6.0/dist/axios.min.js"></script>
        <script>
            document.getElementById('loginForm').addEventListener('submit', async (e) => {
                e.preventDefault();
                const formData = new FormData(e.target);
                const data = Object.fromEntries(formData);
                
                try {
                    const response = await axios.post('/api/auth/login', data);
                    localStorage.setItem('admin_token', response.data.token);
                    localStorage.setItem('admin_name', response.data.name);
                    localStorage.setItem('admin_username', response.data.username);
                    localStorage.setItem('admin_role', response.data.role);
                    localStorage.setItem('organization_id', response.data.organization_id);
                    localStorage.setItem('organization_name', response.data.organization_name || '');
                    window.location.href = '/';
                } catch (error) {
                    const errorDiv = document.getElementById('errorMessage');
                    errorDiv.textContent = error.response?.data?.error || 'ログインに失敗しました。ユーザー名またはパスワードが正しくありません。';
                    errorDiv.classList.remove('hidden');
                }
            });
        </script>
    </body>
    </html>
  `)
})

