// 従業員一覧取得
app.get('/api/admin/users', async (c) => {
  const { DB } = c.env
  const user = await getCurrentUser(c)
  
  // organization_idでテナント分離
  const orgId = user?.organization_id || 1
  
  const users = await DB.prepare(`
    SELECT id, username, name, role, created_at 
    FROM admin_users 
    WHERE organization_id = ?
    ORDER BY created_at DESC
  `).bind(orgId).all()
  
  return c.json(users.results || [])
})

// 従業員追加
app.post('/api/admin/users', async (c) => {
  const { DB } = c.env
  const { username, password, name } = await c.req.json()
  const user = await getCurrentUser(c)
  
  // organization_idでテナント分離
  const orgId = user?.organization_id || 1
  
  // ユーザー名の重複チェック（同じ組織内）
  const existing = await DB.prepare(`
    SELECT id FROM admin_users WHERE username = ? AND organization_id = ?
  `).bind(username, orgId).first()
  
  if (existing) {
    return c.json({ error: 'このユーザー名は既に使用されています' }, 400)
  }
  
  // ユーザー追加（organization_id付き）
  const result = await DB.prepare(`
    INSERT INTO admin_users (username, password_hash, name, organization_id, role)
    VALUES (?, ?, ?, ?, 'staff')
  `).bind(username, password, name, orgId).run()
  
  return c.json({ 
    success: true, 
    id: result.meta.last_row_id,
    message: '従業員を追加しました'
  })
})

// 従業員編集
app.put('/api/admin/users/:id', async (c) => {
  const { DB } = c.env
  const id = c.req.param('id')
  const { username, password, name } = await c.req.json()
  
  // ユーザー名の重複チェック（自分以外）
  const existing = await DB.prepare(`
    SELECT id FROM admin_users WHERE username = ? AND id != ?
  `).bind(username, id).first()
  
  if (existing) {
    return c.json({ error: 'このユーザー名は既に使用されています' }, 400)
  }
  
  // パスワードが空でない場合のみ更新
  if (password) {
    await DB.prepare(`
      UPDATE admin_users 
      SET username = ?, password_hash = ?, name = ?
      WHERE id = ?
    `).bind(username, password, name, id).run()
  } else {
    await DB.prepare(`
      UPDATE admin_users 
      SET username = ?, name = ?
      WHERE id = ?
    `).bind(username, name, id).run()
  }
  
  return c.json({ 
    success: true,
    message: '従業員情報を更新しました'
  })
})

// 従業員削除
app.delete('/api/admin/users/:id', async (c) => {
  const { DB } = c.env
  const id = c.req.param('id')
  
  // admin（ID=1）は削除不可
  if (id === '1') {
    return c.json({ error: 'メイン管理者は削除できません' }, 400)
  }
  
  await DB.prepare(`
    DELETE FROM admin_users WHERE id = ?
  `).bind(id).run()
  
  return c.json({ 
    success: true,
    message: '従業員を削除しました'
  })
})

